import type { HarnessConfig, HarnessFamily, HarnessGrade, HarnessName, HarnessRoute } from "./types.ts";

export const HARNESS_FAMILIES = [
	"grok-build",
	"codex",
	"zcode",
	"qwen-code",
	"deepseek",
] as const satisfies readonly HarnessFamily[];

export const PARENT_HARNESS_NAMES_BY_FAMILY = {
	"grok-build": ["grok-build", "grok-build-plan"],
	codex: ["codex", "codex-plan"],
	zcode: ["zcode", "zcode-plan"],
	"qwen-code": ["qwen-code", "qwen-code-plan"],
	deepseek: ["deepseek-minimal", "deepseek-standard", "deepseek-plan"],
} as const satisfies Record<HarnessFamily, readonly HarnessName[]>;

export const HARNESS_NAMES = [
	...PARENT_HARNESS_NAMES_BY_FAMILY["grok-build"],
	...PARENT_HARNESS_NAMES_BY_FAMILY.codex,
	...PARENT_HARNESS_NAMES_BY_FAMILY.zcode,
	...PARENT_HARNESS_NAMES_BY_FAMILY["qwen-code"],
	...PARENT_HARNESS_NAMES_BY_FAMILY["deepseek"],
] as const satisfies readonly HarnessName[];

export function harnessFamily(name: string | undefined): HarnessFamily | undefined {
	if (!name) return undefined;
	for (const family of HARNESS_FAMILIES) {
		if (PARENT_HARNESS_NAMES_BY_FAMILY[family].includes(name as HarnessName)) {
			return family;
		}
	}
	return undefined;
}

/** No baked model. A name inherits the current Pi model unless config.jsonc sets a grade. */
export const DEFAULT_GRADES: Partial<Record<HarnessName, HarnessGrade>> = {};

export const DEFAULT_HARNESS: HarnessName = "grok-build";

/** Internal route/family value: "no overlay for this model". Not a picker entry. */
export const PI_DEFAULT = "pi-default";

/** Picker entry and command that turn automatic harness selection off. */
export const AUTO_OFF = "off";

/** Picker entry and command that route by model again. */
export const AUTO_ON = "on";

/** Matches both provider/model-id and the raw model id. Earlier routes win. */
export const DEFAULT_HARNESS_ROUTES = [
	{
		match: ["openai/*", "openai-codex/*", "*/openai/*", "*/openai-codex/*", "gpt-*"],
		harness: "codex",
	},
	{
		match: ["xai/*", "x-ai/*", "*/xai/*", "*/x-ai/*", "grok-*"],
		harness: "grok-build",
	},
	{
		match: ["z-ai/*", "zai/*", "*/z-ai/*", "*/zai/*", "glm-*"],
		harness: "zcode",
	},
	{
		match: ["qwen/*", "alibaba/*", "dashscope/*", "*/qwen/*", "*/alibaba/*", "qwen*", "qwq-*"],
		harness: "qwen-code",
	},
	{
		match: ["deepseek/*", "deepseek-ai/*", "*/deepseek/*", "*/deepseek-ai/*", "deepseek-*"],
		harness: "deepseek-minimal",
	},
] as const satisfies readonly HarnessRoute[];

export const DEFAULT_HARNESS_CONFIG: HarnessConfig = {
	default: DEFAULT_HARNESS,
	routes: DEFAULT_HARNESS_ROUTES,
	grades: { ...DEFAULT_GRADES },
};

export function isHarnessName(value: string): value is HarnessName {
	return (HARNESS_NAMES as readonly string[]).includes(value);
}

export function isPiDefault(value: string): boolean {
	return value === PI_DEFAULT || value === "none" || value === "off";
}

/** `off`, plus the legacy `pi-default` / `none` spellings of the same command. */
export function isAutoOff(value: string): boolean {
	return value === AUTO_OFF || isPiDefault(value);
}

/** `/harness:name` or `/harness name` → name. */
export function parseHarnessArg(raw: string): string {
	return raw
		.trim()
		.toLowerCase()
		.replace(/^(harness:|:)/, "");
}

/** The one auto command is named for the direction it applies: `off` while routing is on, `on` while it is off. */
export function autoCommand(autoRoute: boolean | undefined): typeof AUTO_OFF | typeof AUTO_ON {
	return autoRoute === false ? AUTO_ON : AUTO_OFF;
}

export function harnessCommand(name: HarnessName | typeof PI_DEFAULT | typeof AUTO_OFF | typeof AUTO_ON): string {
	return `harness:${name}`;
}

export function harnessLabel(name: HarnessName | typeof PI_DEFAULT | typeof AUTO_OFF | typeof AUTO_ON): string {
	return harnessCommand(name);
}
