import type { HarnessConfig, HarnessFamily, HarnessGrade, HarnessName, HarnessRoute } from "./types.ts";

export const HARNESS_FAMILIES = [
	"grok-build",
	"codex",
	"zcode",
	"qwen-code",
	"deepseek",
] as const satisfies readonly HarnessFamily[];

export const PARENT_HARNESS_NAMES_BY_FAMILY = {
	"grok-build": ["grok-build", "grok-build-plan"],
	codex: ["codex", "codex-plan"],
	zcode: ["zcode", "zcode-plan"],
	"qwen-code": ["qwen-code", "qwen-code-plan"],
	deepseek: ["deepseek-minimal", "deepseek-standard", "deepseek-plan"],
} as const satisfies Record<HarnessFamily, readonly HarnessName[]>;

export const HARNESS_NAMES = [
	...PARENT_HARNESS_NAMES_BY_FAMILY["grok-build"],
	...PARENT_HARNESS_NAMES_BY_FAMILY.codex,
	...PARENT_HARNESS_NAMES_BY_FAMILY.zcode,
	...PARENT_HARNESS_NAMES_BY_FAMILY["qwen-code"],
	...PARENT_HARNESS_NAMES_BY_FAMILY["deepseek"],
] as const satisfies readonly HarnessName[];

export function harnessFamily(name: string | undefined): HarnessFamily | undefined {
	if (!name) return undefined;
	for (const family of HARNESS_FAMILIES) {
		if (PARENT_HARNESS_NAMES_BY_FAMILY[family].includes(name as HarnessName)) {
			return family;
		}
	}
	return undefined;
}

/** No baked model. A name inherits the current Pi model unless config.jsonc sets a grade. */
export const DEFAULT_GRADES: Partial<Record<HarnessName, HarnessGrade>> = {};

export const DEFAULT_HARNESS: HarnessName = "grok-build";

/** Internal route/family value: "no overlay for this model". Not a picker entry. */
export const PI_DEFAULT = "pi-default";

/** Picker entry and command that turn automatic harness selection off. */
export const AUTO_OFF = "off";

/** Picker entry and command that route by model again. */
export const AUTO_ON = "on";

/** Matches both provider/model-id and the raw model id. Earlier routes win. */
export const DEFAULT_HARNESS_ROUTES = [
	{
