export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	const common = input.common && input.family !== "pi-default" ? commonBody(input.root).trim() : "";
	const appendCommon = (text: string, files: string[]): { family: PromptFamily; text: string; files: string[] } => {
		if (!common) return { family: input.family, text, files };
		if (text.includes(common)) {
			return { family: input.family, text, files: files.includes("common.md") ? files : [...files, "common.md"] };
		}
		return {
			family: input.family,
			text: text ? `${text}\n${common}` : common,
			files: [...files, "common.md"],
		};
	};
	if (input.includesFamilyShared || input.family === "pi-default") {
		return appendCommon(rolePrompt, rolePrompt ? ["role"] : []);
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return appendCommon(rolePrompt, rolePrompt ? ["role"] : []);
	}
	if (rolePrompt.includes(shared)) {
		return appendCommon(rolePrompt, [`${input.family}/shared.md`, "role"]);
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return appendCommon(text, rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`]);
}

